if (msg.payload.detections.length > 0) {
    msg.payload = msg.payload.detections[0].id
} else {
    msg.payload = "None"
}

return msg

if (msg.payload.detections.length > 0) {
    msg.payload = msg.payload.detections[0].class_name
} else {
    msg.payload = "None"
}

return msg

// msg.cmd = { command, parameter, timeout, north, east, down, yaw }
// Picks the service by command name. Both services share one request type.
const TAG_NAV = ['center_on_tag', 'fly_until_tag', 'wait_for_tag', 'wait_for_offboard'];
const c = msg.cmd || {};
msg.payload = {
  serviceName: TAG_NAV.includes(c.command) ? '/dexi/tag_nav/execute' : '/dexi/execute_blockly_command',
  serviceType: 'dexi_interfaces/srv/ExecuteBlocklyCommand',
  serviceRequest: { command: c.command, parameter: Number(c.parameter ?? 0), timeout: Number(c.timeout ?? 30),
                    north: Number(c.north ?? 0), east: Number(c.east ?? 0), down: Number(c.down ?? 0), yaw: Number(c.yaw ?? 0),
                    index: 0, r: 0, g: 0, b: 0 },
};
node.status({ fill: 'blue', shape: 'dot', text: `${c.command} ${c.parameter ?? ''}` });
return msg;

// Mission = the route, as tag ids in the order you fly them. Everything else is derived.
// The first step centers on ROUTE[0] (hand over above it); use -1 there to start on whichever tag is in view.
const ROUTE = [0, 1, 2, 3, 4, 5];   // DEXI Lab row east of tag 0; AVR 2026 flies [0, 1, 2, 3, 4, 5, 6]; a lab with tags 0, 2, 4 flies [0, 2, 4]
const FWD = 0.25;   // m/s transit speed; 0.4 outruns the detector under lab light

// Corridor rule until go_to_tag lands on the aircraft: tag ids increase along the corridor,
// so a higher id is ahead (fly forward) and a lower id is behind (fly backward). [0, 2, 4, 2, 0] works.
const STEPS = [{ command: 'center_on_tag', parameter: ROUTE[0], timeout: 25 }];
for (let k = 1; k < ROUTE.length; k++) {
  const tag = ROUTE[k], dir = Math.sign(tag - ROUTE[k - 1]) || 1;
  STEPS.push({ command: 'fly_until_tag', parameter: tag, timeout: 25, north: dir * FWD });
  STEPS.push({ command: 'center_on_tag', parameter: tag, timeout: 25 });
}
STEPS.push({ command: 'land', parameter: 0, timeout: 30 });

let i = context.get('i');
const running = i !== undefined && i !== null && i < STEPS.length;
if (msg.topic === 'start') {
  if (running) return null;
  i = 0;
} else if (msg.topic === 'ok') {
  if (!running) return null;
  i = i + 1;
} else if (msg.topic === 'failed' || msg.topic === 'land_now') {
  context.set('i', null);
  // Land only if the mission still has the aircraft. If the pilot took it back (left Offboard,
  // disengaged), a failed step means "stood down", and landing under a pilot is wrong.
  if (!flow.get('tagnav_go') && msg.topic !== 'land_now') { node.status({ fill: 'grey', shape: 'ring', text: 'failed: pilot has the aircraft' }); return null; }
  node.status({ fill: 'red', shape: 'ring', text: 'failed → land' });
  return [null, { cmd: { command: 'land', parameter: 0, timeout: 30 }, topic: 'land' }];
} else if (msg.topic === 'reset') {
  context.set('i', null); node.status({}); return null;
} else { return null; }
if (i >= STEPS.length) { context.set('i', null); node.status({ fill: 'green', shape: 'dot', text: 'mission complete' }); return null; }
context.set('i', i);
node.status({ fill: 'blue', shape: 'dot', text: `step ${i + 1}/${STEPS.length}: ${STEPS[i].command}` });
return [{ cmd: STEPS[i], topic: 'step' }, null];

// tag_nav publishes JSON at 5 Hz. Output 1: START on the rising edge of "engaged, armed, in OFFBOARD"
// (RC channel 7 or the ENGAGE button), RESET on the falling edge. Output 2: re-arm the hand-off
// stream whenever the aircraft disarms, because landing stops the manager's setpoint stream.
let st = {}; try { st = JSON.parse(msg.payload.data || '{}'); } catch (e) { return null; }
const go = st.engaged === true && st.nav_state === 14 && st.armed === true;
const was = context.get('go') || false;
context.set('go', go); flow.set('tagnav_go', go);   // the mission node reads this on a failure
const armed = st.armed === true, wasArmed = context.get('armed');
context.set('armed', armed); flow.set('tagnav_armed', armed);
let out1 = null, out2 = null;
// trace: last 40 samples the trigger saw (read with GET /context/node/tagnav_edge)
const tr = context.get('trace') || [];
tr.push([new Date().toISOString().slice(11, 23), st.engaged ? 1 : 0, st.nav_state, st.armed ? 1 : 0, go ? 1 : 0]);
while (tr.length > 40) tr.shift();
context.set('trace', tr);
if (go && !was) { node.status({ fill: 'green', shape: 'dot', text: 'hand-off → mission' }); out1 = { topic: 'start' }; }
if (!go && was) { node.status({ fill: 'grey', shape: 'ring', text: 'stood down' }); out1 = { topic: 'reset' }; }
if (wasArmed === true && !armed) out2 = { topic: 'rearm' };
return [out1, out2];

// Stream-only heartbeat: the setpoint follows the aircraft until the pilot enters
// Offboard, then latches where the aircraft is. Never commands Offboard itself.
return { cmd: { command: 'start_setpoint_stream', parameter: 0, timeout: 5 }, topic: 'prep' };

// The button does what the RC switch does: engage tag_nav AND put PX4 in Offboard.
// Offboard needs setpoints flowing, so (re)start the stream first, then switch 600 ms later.
// Disengage drops back to Hold so the pilot has a sane mode to fly out of.
const on = msg.payload && msg.payload.data === true;
if (!on) return { cmd: { command: 'switch_hold_mode', parameter: 0, timeout: 5 }, topic: 'prep' };
node.send({ cmd: { command: 'start_setpoint_stream', parameter: 0, timeout: 5 }, topic: 'prep' });
setTimeout(() => node.send({ cmd: { command: 'switch_offboard_mode', parameter: 0, timeout: 5 }, topic: 'prep' }), 600);
return null;

// Stand-in for the pilot in the simulator. On the aircraft the pilot takes off by hand.
// Sends arm; the takeoff goes out only after PX4 confirms the arm (see 'then takeoff').
return { cmd: { command: 'arm', parameter: 0, timeout: 10 }, topic: 'pilot_arm' };

const ids = (msg.payload.detections || []).map(d => d.id);
const txt = ids.length ? ids.join(', ') : '—';
const now = Date.now(), force = now - (context.get('t') || 0) > 2000;
if (force) context.set('t', now);
if (!force && txt === context.get('last')) return null;
context.set('last', txt);
return { payload: txt };

let st = {}; try { st = JSON.parse(msg.payload.data || '{}'); } catch (e) { return null; }
const NAV = { 0: 'Manual', 1: 'Altitude', 2: 'Position', 3: 'Mission', 4: 'Hold', 14: 'Offboard', 15: 'Stabilized', 17: 'Takeoff', 18: 'Land' };
const vals = [st.armed ? 'armed' : 'disarmed', NAV[st.nav_state] || String(st.nav_state), st.engaged ? 'yes' : 'no', st.state || '—', st.alt != null ? st.alt.toFixed(2) + ' m' : '—'];
const now = Date.now(), force = now - (context.get('t') || 0) > 2000;   // changed rows at once, every row every 2 s (fresh pages, redeploys)
if (force) context.set('t', now);
const last = context.get('last') || [];
context.set('last', vals);
return vals.map((v, i) => (!force && v === last[i]) ? null : { payload: v });

const c = msg.cmd || {};
const p = c.parameter === -1 ? 'any tag' : (c.command.includes('tag') ? 'tag ' + c.parameter : '');
const v = c.north ? ` · ${c.north > 0 ? 'forward' : 'backward'} ${Math.abs(c.north)} m/s` : '';
return { payload: `${c.command.replace(/_/g, ' ')} ${p}` + v };

if ((msg.cmd || {}).command !== 'land') return null;
// the manager stops its setpoint stream when a landing starts; bring it back for the next hand-off
setTimeout(() => node.send({ cmd: { command: 'start_setpoint_stream', parameter: 0, timeout: 5 }, topic: 'prep' }), 2000);
return null;

// msg.payload.detections is an array. Each entry:
//   { class_name: "gasoline", confidence: 0.83, bbox: [x1, y1, x2, y2] }
//
// This takes the first detection and passes its label through.

var detections = msg.payload.detections || [];

if (detections.length === 0) {
    return null;
}

msg.payload = detections[0].class_name;
return msg;

